begin;
set local search_path=public,extensions;
select plan(28);
select ok((select count(*)=8 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['subscription_plans','subscription_plan_versions','plan_entitlements','trial_entitlement_versions','subscriptions','subscription_cycles','subscription_entitlement_suspensions','subscription_state_events'])),'eight subscription records exist');
select ok((select count(*)=8 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['subscription_plans','subscription_plan_versions','plan_entitlements','trial_entitlement_versions','subscriptions','subscription_cycles','subscription_entitlement_suspensions','subscription_state_events'])),'RLS covers all subscription records');
select ok((select count(*)=8 from pg_policies where schemaname='public'and tablename=any(array['subscription_plans','subscription_plan_versions','plan_entitlements','trial_entitlement_versions','subscriptions','subscription_cycles','subscription_entitlement_suspensions','subscription_state_events'])),'each subscription table has a read policy');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name=any(array['subscription_plan_versions','subscription_cycles'])and data_type in('real','double precision')),'prices never use floating point');
select ok((select count(*)>=3 from information_schema.columns where table_schema='public'and table_name=any(array['subscription_plan_versions','subscription_cycles'])and column_name like'%_minor'and data_type='bigint'),'prices use bigint minor units');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and indexname='subscription_plan_one_active_version_idx'),'one active version index exists per plan');
select ok((select count(*)=1 from pg_constraint where conrelid='public.subscription_plan_versions'::regclass and contype='u'and pg_get_constraintdef(oid)like'%plan_id, version%'),'plan version numbers are unique');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.subscription_plan_versions'::regclass and contype='c'and pg_get_constraintdef(oid)like'%core_allocation_basis_points%'and pg_get_constraintdef(oid)like'%benefit_pool_allocation_basis_points%'),'core and benefit allocation is balanced');
select ok((select count(*)=1 from pg_constraint where conrelid='public.plan_entitlements'::regclass and contype='u'and pg_get_constraintdef(oid)like'%plan_version_id, entitlement_code%'),'entitlements are unique per immutable plan version');
select ok(exists(select 1 from pg_constraint where conrelid='public.subscriptions'::regclass and contype='u'and pg_get_constraintdef(oid)='UNIQUE (organization_id)'),'one subscription aggregate exists per organization');
select ok((select count(*)=1 from pg_constraint where conrelid='public.subscription_cycles'::regclass and contype='u'and pg_get_constraintdef(oid)like'%subscription_id, cycle_number%'),'cycle number cannot duplicate');
select ok((select count(*)=1 from pg_constraint where conrelid='public.subscription_cycles'::regclass and contype='u'and pg_get_constraintdef(oid)like'%organization_id, payment_reference%'),'verified payment reference cannot activate twice');
select ok((select count(*)=1 from pg_constraint where conrelid='public.subscription_state_events'::regclass and contype='u'and pg_get_constraintdef(oid)like'%subscription_id, idempotency_key%'),'state events reject replay');
select ok((select count(*)=6 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['subscription_plan_versions','plan_entitlements','trial_entitlement_versions','subscription_cycles','subscription_entitlement_suspensions','subscription_state_events'])and t.tgname like'%_immutable'and not t.tgisinternal),'versions, cycles, suspensions and state history are immutable');
select ok((select count(*)=4 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_trial_subscription','activate_subscription','change_subscription_plan','subscription_has_entitlement'])),'four public subscription functions are hardened');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_trial_subscription','activate_subscription','change_subscription_plan','subscription_has_entitlement'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anon and service role cannot invoke subscription RPCs');
select ok((select count(*)=4 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_trial_subscription','activate_subscription','change_subscription_plan','subscription_has_entitlement'])),'authenticated has explicit RPC execution');
select ok(not has_table_privilege('authenticated','public.subscriptions','UPDATE')and not has_table_privilege('authenticated','public.subscription_cycles','INSERT')and not has_table_privilege('authenticated','public.subscription_state_events','DELETE'),'direct subscription mutation is denied');
select ok((select pg_get_functiondef(p.oid)like'%client_trials%'and pg_get_functiondef(p.oid)like'%VERIFIED_ACTIVATED_CLIENT_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='ensure_trial_subscription'),'trial bridge requires onboarding-created verified trial');
select ok((select pg_get_functiondef(p.oid)like'%trial_started_at%'and pg_get_functiondef(p.oid)like'%trial_ends_at%'and pg_get_functiondef(p.oid)not like'%payment_reference%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='ensure_trial_subscription'),'trial requires no card or payment reference');
select ok((select pg_get_functiondef(p.oid)like'%for update%'and pg_get_functiondef(p.oid)like'%VERIFIED_PAYMENT%'and pg_get_functiondef(p.oid)like'%subscription_cycles%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='activate_subscription'),'activation locks aggregate and records verified paid cycle');
select ok((select pg_get_functiondef(p.oid)like'%monthly_price_minor%'and pg_get_functiondef(p.oid)like'%annual_price_minor%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='activate_subscription'),'cycle price comes from selected immutable plan version');
select ok((select pg_get_functiondef(p.oid)like'%UPGRADE_IMMEDIATE%'and pg_get_functiondef(p.oid)like'%DOWNGRADE_NEXT_CYCLE%'and pg_get_functiondef(p.oid)like'%pending_change_effective_at%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='change_subscription_plan'),'upgrade and scheduled downgrade are explicit');
select ok((select pg_get_functiondef(p.oid)like'%TRIAL_ACTIVE%'and pg_get_functiondef(p.oid)like'%trial_entitlement_versions%'and pg_get_functiondef(p.oid)like'%trial_ends_at%'and pg_get_functiondef(p.oid)like'%status=''ACTIVE''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='subscription_has_entitlement'),'entitlement distinguishes versioned active trial rights and paid active plan');
select ok((select pg_get_functiondef(p.oid)like'%subscription_read_access%'and pg_get_functiondef(p.oid)like'%subscription_entitlement_suspensions%'and pg_get_functiondef(p.oid)like'%entitlement_code%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='subscription_has_entitlement'),'tenant authorization and targeted suspension protect entitlement checks');
select ok((select count(*)=3 and bool_and(pg_get_functiondef(p.oid)like'%begin_subscription_command%'and pg_get_functiondef(p.oid)like'%finish_subscription_command%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_trial_subscription','activate_subscription','change_subscription_plan'])),'all subscription mutations use canonical idempotence');
select ok((select count(*)=3 and bool_and(pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%event_outbox%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['ensure_trial_subscription','activate_subscription','change_subscription_plan'])),'all subscription mutations emit audit and Outbox');
select ok((select count(*)=5 from pg_indexes where schemaname='public'and indexname=any(array['subscription_plan_versions_active_idx','subscriptions_org_status_idx','subscription_cycles_time_idx','entitlement_suspensions_active_idx','subscription_state_events_time_idx'])),'subscription operational indexes exist');
select*from finish();rollback;
